package com.camjewell.gotrgoals;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.QuantityFormatter;

/**
 * Estimates how many more games until the level and reward goals are met, from rolling averages
 * over the player's last {@link GotrGoalsConfig#gamesWindow()} games:
 * <ul>
 *     <li>Level: XP still needed / average Runecraft XP per game.</li>
 *     <li>Reward: pearls still needed / expected pearls per search = searches needed; each search
 *     costs one elemental and one catalytic point, so games = the larger of each type's shortfall
 *     (after banked points and this game's energy so far) / that type's average points per game.</li>
 * </ul>
 * Values drawn from the configured assumptions rather than real games are shown in gray. Every
 * row is kept short (label + a number or two) so it fits the narrow default width without
 * wrapping; the supporting detail (searches needed, how many games the averages cover, the
 * averages themselves) is in a hover tooltip instead, so the overlay is just the answers.
 */
class EstimateOverlay extends OverlayPanel
{
	private static final Color ASSUMED_COLOR = Color.LIGHT_GRAY;

	private final GotrGoalsPlugin plugin;
	private final GotrGoalsConfig config;
	private final Client client;
	private final TooltipManager tooltipManager;

	@Inject
	EstimateOverlay(GotrGoalsPlugin plugin, GotrGoalsConfig config, Client client, TooltipManager tooltipManager)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.client = client;
		this.tooltipManager = tooltipManager;

		setPosition(OverlayPosition.TOP_RIGHT);
		setPriority(PRIORITY_LOW);
		panelComponent.setPreferredSize(new Dimension(GoalOverlay.PREFERRED_WIDTH, 0));
		panelComponent.setBorder(new Rectangle(3, 3, 3, 3));
		panelComponent.setGap(new Point(0, 2));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showEstimatesOverlay())
		{
			return null;
		}

		Goal goal = plugin.getGoal();
		boolean showRewards = !goal.getSelected().isEmpty();
		if (!showRewards && !goal.isLevelGoalEnabled())
		{
			return null;
		}
		if (config.onlyShowAtGotr() && !plugin.isAtGotr())
		{
			return null;
		}

		graphics.setFont(FontManager.getRunescapeSmallFont());

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Games remaining")
			.leftFont(FontManager.getRunescapeBoldFont())
			.build());

		if (goal.isLevelGoalEnabled())
		{
			addLevelRow(goal);
		}
		Integer searchesNeeded = showRewards ? addRewardRow(goal) : null;

		Dimension dimension = super.render(graphics);

		// getBounds() is where the overlay was last drawn, which is where the mouse is pointing.
		net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		if (mouse != null && getBounds().contains(mouse.getX(), mouse.getY()))
		{
			tooltipManager.add(new Tooltip(basisTooltip(searchesNeeded)));
		}

		return dimension;
	}

	private void addLevelRow(Goal goal)
	{
		String label = goal.isTargetXpOverride()
			? QuantityFormatter.quantityToStackSize(goal.getTargetXp()) + " xp:"
			: "Level " + goal.getTargetLevel() + ":";

		int xpRemaining = goal.getXpRemaining();
		if (xpRemaining <= 0)
		{
			addRow(label, "Done", Color.GREEN);
			return;
		}

		Integer games = Goal.gamesForXp(xpRemaining, plugin.getXpPerGame());
		if (games == null)
		{
			addRow(label, "play a game", Color.GRAY);
			return;
		}

		addRow(label, formatGames(games), plugin.isXpPerGameObserved() ? Color.WHITE : ASSUMED_COLOR);
	}

	/**
	 * @return the searches still needed (shown in the basis rows), or null if the goal is met
	 */
	private Integer addRewardRow(Goal goal)
	{
		int pearlsRemaining = goal.getPearlsRemaining();
		if (pearlsRemaining <= 0)
		{
			addRow("Rewards:", "Done", Color.GREEN);
			return null;
		}

		int searchesNeeded = Goal.searchesForPearls(pearlsRemaining, plugin.getPearlsPerSearch());

		// Without knowing what's banked, a games estimate would count every banked point as still
		// needing to be earned - better to say so than show a confidently wrong number.
		if (!plugin.isPointsKnown())
		{
			addRow("Rewards:", "Check guardian", Color.GRAY);
			return searchesNeeded;
		}

		double haveElemental = plugin.getElementalPoints()
			+ plugin.getCurrentGameElementalEnergy() / Goal.ENERGY_PER_POINT;
		double haveCatalytic = plugin.getCatalyticPoints()
			+ plugin.getCurrentGameCatalyticEnergy() / Goal.ENERGY_PER_POINT;

		Integer games = Goal.gamesForSearches(searchesNeeded, haveElemental, haveCatalytic,
			plugin.getElementalPerGame(), plugin.getCatalyticPerGame());
		if (games == null)
		{
			addRow("Rewards:", "play a game", Color.GRAY);
		}
		else if (games == 0)
		{
			addRow("Rewards:", "Search now", Color.GREEN);
		}
		else
		{
			addRow("Rewards:", formatGames(games), plugin.isPointsPerGameObserved() ? Color.WHITE : ASSUMED_COLOR);
		}
		return searchesNeeded;
	}

	/**
	 * Hover text saying what the estimates are based on, so a wild number from a single unusual
	 * game reads as such.
	 */
	private String basisTooltip(Integer searchesNeeded)
	{
		List<String> lines = new ArrayList<>();
		if (searchesNeeded != null)
		{
			lines.add("Searches needed: " + QuantityFormatter.formatNumber(searchesNeeded));
			lines.add(String.format("Pearls / search: %.2f", plugin.getPearlsPerSearch()));
		}

		int games = plugin.getHistory().countInWindow(config.gamesWindow());
		if (games == 0)
		{
			boolean assumed = config.assumedXpPerGame() > 0 || config.assumedPointsPerGame() > 0;
			lines.add(assumed ? "Using assumed rates (gray) until a game is recorded" : "No games recorded yet");
			return String.join("</br>", lines);
		}

		lines.add("Averaged over: " + games + (games == 1 ? " game" : " games"));
		if (plugin.getXpPerGame() != null && plugin.isXpPerGameObserved())
		{
			lines.add("XP / game: " + QuantityFormatter.quantityToStackSize(Math.round(plugin.getXpPerGame())));
		}
		if (plugin.getElementalPerGame() != null && plugin.getCatalyticPerGame() != null)
		{
			lines.add(String.format("Points / game: %.1f elemental, %.1f catalytic",
				plugin.getElementalPerGame(), plugin.getCatalyticPerGame()));
		}
		if (plugin.getMinutesPerGame() != null)
		{
			lines.add(String.format("Time / game: %.1f min", plugin.getMinutesPerGame()));
		}
		return String.join("</br>", lines);
	}

	private String formatGames(int games)
	{
		String text = QuantityFormatter.formatNumber(games);
		if (config.showTimeEstimates() && plugin.getMinutesPerGame() != null)
		{
			text += " (~" + formatMinutes(games * plugin.getMinutesPerGame()) + ")";
		}
		return text;
	}

	private static String formatMinutes(double minutes)
	{
		if (minutes < 60)
		{
			return Math.max(1, (int) Math.ceil(minutes)) + "m";
		}
		return String.format("%.1fh", minutes / 60.0);
	}

	private void addRow(String left, String right, Color rightColor)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(left)
			.leftFont(FontManager.getRunescapeFont())
			.right(right)
			.rightFont(FontManager.getRunescapeFont())
			.rightColor(rightColor)
			.build());
	}
}

package com.camjewell.gotrgoals;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Iterator;
import java.util.List;

/**
 * The player's most recent completed Guardians of the Rift games, used to average XP and reward
 * points per game. Unlike MTA's per-tick rate windows this is a per-game window: games are
 * ~10 minutes long and vary a lot (mass vs. solo, combination runes, leaving early), so the
 * natural unit is "the last N games" rather than "the last N minutes".
 *
 * Stored as a plain "xp,elemental,catalytic,ticks;..." string in the RuneScape-profile config so
 * estimates survive client restarts - with one data point per ~10 minutes, throwing the history
 * away on logout (as MTA does with its per-tick windows) would leave the estimates empty for most
 * of every session.
 */
class GameHistory
{
	/**
	 * Hard cap on stored samples, independent of {@link GotrGoalsConfig#gamesWindow()} (which is
	 * capped lower), so the persisted string stays small however long someone plays.
	 */
	static final int MAX_STORED_GAMES = 100;

	static final int UNKNOWN = -1;

	private final Deque<Sample> samples = new ArrayDeque<>();

	void add(Sample sample)
	{
		samples.addLast(sample);
		while (samples.size() > MAX_STORED_GAMES)
		{
			samples.removeFirst();
		}
	}

	void clear()
	{
		samples.clear();
	}

	int size()
	{
		return samples.size();
	}

	/**
	 * @return mean Runecraft XP over the last {@code window} games whose XP was measured, or null
	 * if none were (e.g. every recent game was joined part-way through).
	 */
	Double averageXp(int window)
	{
		return average(window, Sample::xp);
	}

	Double averageElemental(int window)
	{
		return average(window, Sample::elemental);
	}

	Double averageCatalytic(int window)
	{
		return average(window, Sample::catalytic);
	}

	/**
	 * @return mean real-world ticks per game (including the wait before it, when the previous game
	 * was played back-to-back) over the last {@code window} games, or null if unmeasured.
	 */
	Double averageTicks(int window)
	{
		return average(window, Sample::ticks);
	}

	/**
	 * @return how many of the last {@code window} games the averages are drawn from.
	 */
	int countInWindow(int window)
	{
		return Math.min(Math.max(window, 1), samples.size());
	}

	private Double average(int window, SampleField field)
	{
		int remaining = Math.max(window, 1);
		long total = 0;
		int count = 0;
		Iterator<Sample> it = samples.descendingIterator();
		while (it.hasNext() && remaining > 0)
		{
			int value = field.get(it.next());
			remaining--;
			if (value == UNKNOWN)
			{
				continue;
			}
			total += value;
			count++;
		}
		return count == 0 ? null : total / (double) count;
	}

	String serialize()
	{
		StringBuilder sb = new StringBuilder();
		for (Sample s : samples)
		{
			if (sb.length() > 0)
			{
				sb.append(';');
			}
			sb.append(s.xp()).append(',')
				.append(s.elemental()).append(',')
				.append(s.catalytic()).append(',')
				.append(s.ticks());
		}
		return sb.toString();
	}

	/**
	 * Replaces the current history with the parsed one. Malformed entries are skipped rather than
	 * failing the whole load, so one bad entry never wipes out every other game.
	 *
	 * Entries with unknown XP are dropped too: early versions recorded games joined part-way (with
	 * unknown XP and usually 0 points), which dragged the points average down. Games are only
	 * recorded when their start was seen now, so this cleans those out of saved history.
	 */
	void deserialize(String value)
	{
		samples.clear();
		if (value == null || value.isEmpty())
		{
			return;
		}
		List<Sample> parsed = new ArrayList<>();
		for (String entry : value.split(";"))
		{
			String[] parts = entry.split(",");
			if (parts.length != 4)
			{
				continue;
			}
			try
			{
				parsed.add(new Sample(
					Integer.parseInt(parts[0].trim()),
					Integer.parseInt(parts[1].trim()),
					Integer.parseInt(parts[2].trim()),
					Integer.parseInt(parts[3].trim())));
			}
			catch (NumberFormatException e)
			{
				// skip this entry only
			}
		}
		for (Sample s : parsed)
		{
			if (s.xp() != UNKNOWN)
			{
				add(s);
			}
		}
	}

	private interface SampleField
	{
		int get(Sample sample);
	}

	static final class Sample
	{
		private final int xp;
		private final int elemental;
		private final int catalytic;
		private final int ticks;

		/**
		 * @param xp        Runecraft XP gained over the game (crafting + the end-of-game bonus), or
		 *                  {@link #UNKNOWN} - only in history saved by early versions, which still
		 *                  recorded games joined part-way; those aren't recorded at all now
		 * @param elemental elemental reward points awarded at the end of the game
		 * @param catalytic catalytic reward points awarded at the end of the game
		 * @param ticks     game ticks the game took, or {@link #UNKNOWN}
		 */
		Sample(int xp, int elemental, int catalytic, int ticks)
		{
			this.xp = xp;
			this.elemental = elemental;
			this.catalytic = catalytic;
			this.ticks = ticks;
		}

		int xp()
		{
			return xp;
		}

		int elemental()
		{
			return elemental;
		}

		int catalytic()
		{
			return catalytic;
		}

		int ticks()
		{
			return ticks;
		}
	}
}

package com.camjewell.gotrgoals;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Experience;

/**
 * Aggregates the ticked Temple Supplies rewards into one combined pearl target, tracks the
 * Runecraft level/XP target, and holds the pure math the estimate overlay uses to turn "pearls
 * or XP still needed" into "games still needed".
 *
 * The reward chain is pearls -> searches -> reward points -> games: shop items cost pearls,
 * pearls only come (randomly) from Rewards Guardian searches, each search costs one elemental and
 * one catalytic point, and points are awarded at the end of each game.
 */
class Goal
{
	/**
	 * Abyssal pearls roll as 14-16 (15 on average) on the Rewards Guardian's "other" table, at
	 * 18/140 per search - or 18/125 once the player owns every essence pouch (or a colossal
	 * pouch), since the pouch slots then drop out of the table. Per the OSRS Wiki's Rewards
	 * Guardian drop table, post-November 2024 changes.
	 */
	private static final double PEARLS_PER_HIT = 15.0;
	private static final double PEARL_RATE_WITH_POUCHES_TABLE = 18.0 / 140.0;
	private static final double PEARL_RATE_ALL_POUCHES_OWNED = 18.0 / 125.0;

	/**
	 * Expected extra pearls per search from selling the Rewards Guardian's dyes (1/400, 50 pearls
	 * each) and abyssal lanterns (1/700, 100 pearls each) back to Apprentice Felix.
	 */
	private static final double TRADE_IN_PEARLS_PER_SEARCH = 50.0 / 400.0 + 100.0 / 700.0;

	/**
	 * One reward point is awarded per 100 energy of that type at the end of a game (with the
	 * remainder as a percent chance of one more), so mid-game energy is worth energy/100 points.
	 */
	static final double ENERGY_PER_POINT = 100.0;

	private final List<RewardItem> selected = new ArrayList<>();
	private String displayName = "";
	private RewardItem representativeItem = RewardItem.NONE;

	private int pearlGoal = 0;
	private int pearlsOwned = 0;
	private boolean metThreshold = false;

	private boolean levelGoalEnabled = false;
	private int currentXp = 0;
	private int currentLevel = 1;
	private int targetXp = 0;
	private int targetLevel = 1;
	private boolean targetXpOverride = false;

	List<RewardItem> getSelected()
	{
		return selected;
	}

	String getDisplayName()
	{
		return displayName;
	}

	RewardItem getRepresentativeItem()
	{
		return representativeItem;
	}

	int getPearlGoal()
	{
		return pearlGoal;
	}

	int getPearlsOwned()
	{
		return pearlsOwned;
	}

	int getPearlsRemaining()
	{
		return Math.max(pearlGoal - pearlsOwned, 0);
	}

	double getPearlProgress()
	{
		return pearlGoal == 0 ? 1.0 : Math.min((double) pearlsOwned / pearlGoal, 1.0);
	}

	boolean isMetThreshold()
	{
		return metThreshold;
	}

	boolean isLevelGoalEnabled()
	{
		return levelGoalEnabled;
	}

	int getCurrentXp()
	{
		return currentXp;
	}

	int getCurrentLevel()
	{
		return currentLevel;
	}

	int getTargetXp()
	{
		return targetXp;
	}

	int getTargetLevel()
	{
		return targetLevel;
	}

	/**
	 * @return true if the target is an exact XP amount rather than a level
	 */
	boolean isTargetXpOverride()
	{
		return targetXpOverride;
	}

	int getXpRemaining()
	{
		return Math.max(targetXp - currentXp, 0);
	}

	double getXpProgress()
	{
		return targetXp == 0 ? 1.0 : Math.min((double) currentXp / targetXp, 1.0);
	}

	void recalculate(GotrGoalsConfig config, int pearlsOwned, int currentXp)
	{
		selected.clear();
		if (config.trackHatOfTheEye())
		{
			selected.add(RewardItem.HAT_OF_THE_EYE);
		}
		if (config.trackRobeTopOfTheEye())
		{
			selected.add(RewardItem.ROBE_TOP_OF_THE_EYE);
		}
		if (config.trackRobeBottomsOfTheEye())
		{
			selected.add(RewardItem.ROBE_BOTTOMS_OF_THE_EYE);
		}
		if (config.trackBootsOfTheEye())
		{
			selected.add(RewardItem.BOOTS_OF_THE_EYE);
		}
		if (config.trackRingOfTheElements())
		{
			selected.add(RewardItem.RING_OF_THE_ELEMENTS);
		}
		if (config.trackAbyssalNeedle())
		{
			selected.add(RewardItem.ABYSSAL_NEEDLE);
		}
		if (config.trackAbyssalLantern())
		{
			selected.add(RewardItem.ABYSSAL_LANTERN);
		}
		if (config.trackGuardiansEye())
		{
			selected.add(RewardItem.GUARDIANS_EYE);
		}

		if (selected.isEmpty())
		{
			displayName = "";
			representativeItem = RewardItem.NONE;
		}
		else if (selected.size() == 1)
		{
			displayName = selected.get(0).itemName();
			representativeItem = selected.get(0);
		}
		else
		{
			displayName = "Selected rewards (" + selected.size() + ")";
			representativeItem = selected.get(0);
		}

		int goal = 0;
		for (RewardItem item : selected)
		{
			goal += item.pearlCost();
		}
		this.pearlGoal = goal;
		this.pearlsOwned = pearlsOwned;
		this.metThreshold = !selected.isEmpty() && pearlsOwned >= pearlGoal;

		this.levelGoalEnabled = config.trackLevelGoal();
		this.currentXp = currentXp;
		// getLevelForXp() goes up to virtual level 126; only real levels are meaningful here.
		this.currentLevel = Math.min(Experience.getLevelForXp(currentXp), Experience.MAX_REAL_LEVEL);
		this.targetXpOverride = config.targetXp() > 0;
		if (targetXpOverride)
		{
			this.targetXp = Math.min(config.targetXp(), Experience.MAX_SKILL_XP);
			this.targetLevel = Math.min(Experience.getLevelForXp(this.targetXp), Experience.MAX_REAL_LEVEL);
		}
		else
		{
			// 0 means "next level", so the default is useful at any level without configuring.
			int level = config.targetLevel() > 0 ? config.targetLevel() : currentLevel + 1;
			this.targetLevel = Math.max(2, Math.min(level, Experience.MAX_REAL_LEVEL));
			this.targetXp = Experience.getXpForLevel(this.targetLevel);
		}
	}

	/**
	 * @return expected Abyssal pearls per Rewards Guardian search
	 */
	static double pearlsPerSearch(boolean ownAllPouches, boolean countTradeIns)
	{
		double rate = PEARLS_PER_HIT * (ownAllPouches ? PEARL_RATE_ALL_POUCHES_OWNED : PEARL_RATE_WITH_POUCHES_TABLE);
		return countTradeIns ? rate + TRADE_IN_PEARLS_PER_SEARCH : rate;
	}

	/**
	 * @return expected searches (each costing one elemental and one catalytic point) to earn the
	 * given pearls
	 */
	static int searchesForPearls(int pearlsRemaining, double pearlsPerSearch)
	{
		if (pearlsRemaining <= 0 || pearlsPerSearch <= 0)
		{
			return 0;
		}
		// The epsilon keeps floating-point noise (e.g. 1350 / 2.16 = 625.0000000001) from rounding
		// an exact answer up by one.
		return (int) Math.ceil(pearlsRemaining / pearlsPerSearch - 1e-9);
	}

	/**
	 * Games still needed to have {@code searchesNeeded} of BOTH point types, since every search
	 * spends one of each - so whichever type is further behind (after what's banked and what's
	 * already been earned this game) is the bottleneck.
	 *
	 * @param haveElemental banked elemental points plus this game's energy so far / 100
	 * @param haveCatalytic banked catalytic points plus this game's energy so far / 100
	 * @param avgElemental  elemental points earned per game, or null if unknown
	 * @param avgCatalytic  catalytic points earned per game, or null if unknown
	 * @return games remaining (0 if enough points are already banked), or null if a type is still
	 * short and there's no positive per-game rate for it to estimate from
	 */
	static Integer gamesForSearches(int searchesNeeded, double haveElemental, double haveCatalytic,
		Double avgElemental, Double avgCatalytic)
	{
		Double elementalGames = gamesForDeficit(searchesNeeded - haveElemental, avgElemental);
		Double catalyticGames = gamesForDeficit(searchesNeeded - haveCatalytic, avgCatalytic);
		if (elementalGames == null || catalyticGames == null)
		{
			return null;
		}
		return (int) Math.ceil(Math.max(elementalGames, catalyticGames));
	}

	/**
	 * @return games to gain {@code xpRemaining}, 0 if already there, or null without a rate
	 */
	static Integer gamesForXp(int xpRemaining, Double avgXpPerGame)
	{
		Double games = gamesForDeficit(xpRemaining, avgXpPerGame);
		return games == null ? null : (int) Math.ceil(games);
	}

	private static Double gamesForDeficit(double deficit, Double perGame)
	{
		if (deficit <= 0)
		{
			return 0.0;
		}
		if (perGame == null || perGame <= 0)
		{
			return null;
		}
		return deficit / perGame;
	}
}

package com.camjewell.gotrgoals;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.text.DecimalFormat;
import javax.inject.Inject;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.SplitComponent;
import net.runelite.client.util.QuantityFormatter;

/**
 * Pearl progress toward the ticked Temple Supplies rewards. The level goal has its own
 * {@link LevelOverlay}, since the two goals are unrelated.
 *
 * Each bar's name and current/goal amounts sit on a text line above it, leaving only percent and
 * remaining on the bar itself - a bar has no room to wrap, so packing three labels into it
 * overprinted them at anything narrower than ~250px.
 */
class GoalOverlay extends OverlayPanel
{
	static final int PREFERRED_WIDTH = 150;

	private static final DecimalFormat DECIMAL_FORMAT = new DecimalFormat("0.0");
	private static final int BORDER_SIZE = 3;
	private static final int VERTICAL_GAP = 2;
	private static final int ICON_GAP = 5;
	private static final Rectangle TOP_PANEL_BORDER = new Rectangle(2, 0, 4, 4);
	private static final Color PROGRESS_BAR_BACKGROUND_COLOR = new Color(61, 56, 49);
	private static final Color PEARL_COLOR = Color.decode("#4dd0e1");

	private final GotrGoalsPlugin plugin;
	private final GotrGoalsConfig config;
	private final ItemManager itemManager;

	private final PanelComponent topPanel = new PanelComponent();

	private BufferedImage cachedRewardIcon;
	private RewardItem cachedRewardItem;

	@Inject
	GoalOverlay(GotrGoalsPlugin plugin, GotrGoalsConfig config, ItemManager itemManager)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;

		setPosition(OverlayPosition.TOP_RIGHT);
		setPriority(PRIORITY_MED);
		panelComponent.setPreferredSize(new Dimension(PREFERRED_WIDTH, 0));
		panelComponent.setBorder(new Rectangle(BORDER_SIZE, BORDER_SIZE, BORDER_SIZE, BORDER_SIZE));
		panelComponent.setGap(new Point(0, VERTICAL_GAP));

		topPanel.setBorder(TOP_PANEL_BORDER);
		topPanel.setBackgroundColor(null);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Goal goal = plugin.getGoal();

		if (goal.getSelected().isEmpty())
		{
			return null;
		}
		if (config.onlyShowAtGotr() && !plugin.isAtGotr())
		{
			return null;
		}

		graphics.setFont(FontManager.getRunescapeSmallFont());

		addRewardHeader(goal);
		addPearlSection(goal);
		addFooter();

		return super.render(graphics);
	}

	private void addRewardHeader(Goal goal)
	{
		topPanel.getChildren().clear();

		String name = goal.getSelected().size() == 1
			? goal.getDisplayName()
			: goal.getSelected().size() + " rewards";
		var topLine = LineComponent.builder()
			.left(name)
			.leftFont(FontManager.getRunescapeFont())
			.build();

		var bottomLine = LineComponent.builder()
			.left("Progress:")
			.leftFont(FontManager.getRunescapeFont())
			.right(DECIMAL_FORMAT.format(goal.getPearlProgress() * 100) + "%")
			.rightFont(FontManager.getRunescapeFont())
			.rightColor(goal.isMetThreshold() ? Color.GREEN : Color.WHITE)
			.build();

		var textSplit = SplitComponent.builder()
			.first(topLine)
			.second(bottomLine)
			.orientation(ComponentOrientation.VERTICAL)
			.build();

		var rewardImageComponent = new ImageComponent(getRewardImage(goal.getRepresentativeItem()));
		var topInfoSplit = SplitComponent.builder()
			.first(rewardImageComponent)
			.second(textSplit)
			.orientation(ComponentOrientation.HORIZONTAL)
			.gap(new Point(ICON_GAP, 0))
			.build();

		topPanel.getChildren().add(topInfoSplit);
		panelComponent.getChildren().add(topPanel);
	}

	private void addPearlSection(Goal goal)
	{
		panelComponent.getChildren().add(labelLine("Pearls", QuantityFormatter.quantityToStackSize(goal.getPearlsOwned())
			+ "/" + QuantityFormatter.quantityToStackSize(goal.getPearlGoal())));

		var progressBar = newBar(PEARL_COLOR, goal.getPearlProgress());

		// Banked reward points are pearls-in-waiting: tint the part of the remaining bar that
		// searching them would be expected to fill, the same way MTA Goals tints Alchemist gold
		// that's held but not yet deposited.
		if (plugin.isPointsKnown() && goal.getPearlGoal() > 0)
		{
			double expectedPearls = plugin.getBankedSearches() * plugin.getPearlsPerSearch();
			double pendingFraction = expectedPearls / goal.getPearlGoal();
			if (pendingFraction > 0)
			{
				progressBar.setPendingPercentage(pendingFraction);
				progressBar.setPendingColor(new Color(PEARL_COLOR.getRed(), PEARL_COLOR.getGreen(), PEARL_COLOR.getBlue(), 120));
			}
		}

		progressBar.setCenterLabel(centerLabel(config.showPercentages(), goal.getPearlProgress(), goal.getPearlsRemaining()));
		panelComponent.getChildren().add(progressBar);
	}

	private void addFooter()
	{
		if (config.showPointsLine())
		{
			if (plugin.isPointsKnown())
			{
				addSmallLine("Points:", QuantityFormatter.formatNumber(plugin.getElementalPoints())
					+ " / " + QuantityFormatter.formatNumber(plugin.getCatalyticPoints()), Color.WHITE);
			}
			else
			{
				addSmallLine("Points:", "Check guardian", Color.GRAY);
			}
		}

		if (!plugin.isBankPearlsKnown())
		{
			addSmallLine("Bank pearls:", "open bank", Color.GRAY);
		}
	}

	static OutlinedProgressBarComponent newBar(Color color, double progress)
	{
		var progressBar = new OutlinedProgressBarComponent();
		progressBar.setForegroundColor(color);
		progressBar.setBackgroundColor(PROGRESS_BAR_BACKGROUND_COLOR);
		progressBar.setPercentage(progress);
		return progressBar;
	}

	/**
	 * The text line that sits above a bar: its name on the left, current/goal on the right.
	 */
	static LineComponent labelLine(String left, String right)
	{
		return LineComponent.builder()
			.left(left)
			.leftFont(FontManager.getRunescapeSmallFont())
			.right(right)
			.rightFont(FontManager.getRunescapeSmallFont())
			.build();
	}

	private void addSmallLine(String left, String right, Color color)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(left)
			.leftFont(FontManager.getRunescapeSmallFont())
			.right(right)
			.rightColor(color)
			.rightFont(FontManager.getRunescapeSmallFont())
			.build());
	}

	static String centerLabel(boolean showPercentage, double progress, int remaining)
	{
		String remainingText = remaining > 0 ? "(" + QuantityFormatter.quantityToStackSize(remaining) + ")" : "";
		if (showPercentage)
		{
			String percentText = DECIMAL_FORMAT.format(progress * 100) + "%";
			return remainingText.isEmpty() ? percentText : percentText + " " + remainingText;
		}
		return remainingText;
	}

	private BufferedImage getRewardImage(RewardItem rewardItem)
	{
		if (cachedRewardItem != rewardItem)
		{
			cachedRewardItem = rewardItem;
			cachedRewardIcon = itemManager.getImage(rewardItem.itemId());
		}
		return cachedRewardIcon;
	}
}

